public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] bytes = schema.encode(message, buffer);
    int size = bytes.length;
    out.write(size >>> 8); // write high byte
    out.write(size & 0xFF); // write low byte
    out.write(bytes);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int serializedSize = schema.getByteCount(message, buffer);
    ByteBuffer tempBuffer = allocate(serializedSize + 5);

    tempBuffer.putInt(serializedSize);
    schema.writeTo(tempBuffer, message, buffer);

    int size = tempBuffer.position();
    tempBuffer.flip();

    out.write(tempBuffer.array(), 0, size);

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int expectedSize = schema.getSerializedSize(message);
    buffer = resize(buffer, expectedSize + 5);
    buffer.clear();
    buffer.writeByte((byte)(expectedSize >>> 24));
    buffer.writeByte((byte)(expectedSize >>> 16));
    buffer.writeByte((byte)(expectedSize >>> 8));
    buffer.writeByte((byte)expectedSize);
    schema.writeTo(buffer, message);
    writeRawBytes(out, buffer);
    return expectedSize + 4;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    byte[] dataArray = schema.toBytes(message);
    int dataLength = dataArray.length;

    if (dataLength > buffer.maxBufferSize - 5) {
        throw new IOException("Message is too large to fit in the buffer");
    }

    buffer.writeLittleEndianInt(out, dataLength);
    out.write(dataArray);
    return dataLength;
}

