static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day components from the time bucket
    int year = (int) (timeBucket / 10000L);
    int month = (int) ((timeBucket / 100L) % 100);
    int day = (int) (timeBucket % 100);

    // Calculate the new day by subtracting the dayStep
    day -= dayStep;

    // Handle negative days by adjusting the month and year
    while (day < 1) {
        if (month == 1) { // January
            month = 12;
            year--;
        } else {
            month--;
        }
        day += 31; // Maximum number of days in any month (not considering leap years)
    }

    // Handle cases where the month has less than 31 days
    if (day > 30) {
        if (month == 4 || month == 6 || month == 9 || month == 11) {
            day = 30;
        }
    }

    if (day > 31) {
        if (month == 2) { // February
            day = 28; // Not considering leap years
        } else {
            day = 31;
        }
    }

    // Reconstruct the new time bucket
    return (long) (year * 10000L + month * 100L + day);
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index > str.length()) {
        throw new IllegalArgumentException("Invalid starting index");
    }
    if (len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid length");
    }

    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < len && Character.isSurrogatePair(c, str.charAt(index + i + 1))) {
                size += 4;
                i++; // Skip the next char as it is part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

