protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return graph.createPath(graph.getVertexes().iterator().next());
    }

    V startVertex = edges.get(0).getV(); // or getU(), assuming the tour is valid
    GraphPath<V, E> path = graph.createPath(startVertex);

    for (E edge : edges) {
        path = graph.createPath(path, edge);
    }

    return path;
}

