protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    Iterator<E> edgeIterator = edgeList.iterator();
    V startVertex = edgeIterator.next().getTarget();
    V currentVertex = startVertex;
    GraphPath<V,E> path = new DefaultGraphPath<>(graph, startVertex);

    while (edgeIterator.hasNext()) {
        E edge = edgeIterator.next();
        V nextVertex = edge.getTarget();
        if (!nextVertex.equals(currentVertex)) {
            path = path.extend(nextVertex, edge);
            currentVertex = nextVertex;
        }
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    List<E> edges = new ArrayList<>(tour);
    V startVertex = null;
    V endVertex = null;

    if (!edges.isEmpty()) {
        startVertex = edges.get(0).getEndpoint(0);
        endVertex = edges.get(edges.size() - 1).getEndpoint(1);
    } else {
        // If the tour is empty, treat the start and end vertex as the same
        // This might not be the correct behavior always, but it's a simple way to handle an empty tour
        startVertex = graph.getVertices().iterator().next();
        endVertex = startVertex;
    }

    return new GraphWalk<>(graph, startVertex, endVertex, edges);
}

