public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null) {
        return 0;
    }
    int count = 0;
    int fromIndex = 0;
    while (fromIndex != -1) {
        fromIndex = str.indexOf(sub, fromIndex);
        if (fromIndex != -1) {
            count++;
            fromIndex += sub.length();
        }
    }
    return count;
}

