public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and pane cannot be null");
    }

    JViewport viewport = pane.getViewport();
    if (viewport == null) {
        throw new IllegalStateException("Viewport is null");
    }

    table.setRowSelectionInterval(row, row);
    int rowHeight = table.getRowHeight();
    int visibleRows = viewport.getViewSize().height / rowHeight;
    int startRow = table.getFirstVisibleRow();
    int endRow = startRow + visibleRows - 1;

    if (row < startRow || row > endRow) {
        int rectX = 0;
        int rectY = (row - startRow) * rowHeight;
        int rectWidth = viewport.getWidth();
        int rectHeight = rowHeight;
        Rectangle visibleRect = new Rectangle(rectX, rectY, rectWidth, rectHeight);
        viewport.setViewRect(visibleRect);
    }

    SwingUtilities.invokeLater(() -> table.repaint());
}

